import { Router } from "express";
import { userController } from "../controllers/user.controller";
import { authMiddleware } from "../middleware/auth.middleware";
import { commonMiddleware } from "../middleware/common.middleware";
import { UserValidator } from "../validators/user.validator";
const router = Router();
router.get("/", userController.getAll);
router.get("/:id", commonMiddleware.isValidated("id"), userController.getById);
router.patch("/:id", authMiddleware.checkAccessToken, commonMiddleware.isValidated("id"), commonMiddleware.validateBody(UserValidator.update), userController.updateById);
router.delete("/:id", authMiddleware.checkAccessToken, commonMiddleware.isValidated("id"), userController.deleteById);
router.delete("/", userController.deleteAll);
router.patch("/:id/block", authMiddleware.checkAccessToken, authMiddleware.isAdmin, userController.blockUser);
router.patch("/:id/unblock", authMiddleware.checkAccessToken, authMiddleware.isAdmin, userController.unBlockUser);
export const userRouter = router;
